Method.Implementation:
	SET $NAMESPACE = "%SYS"
	set statement = ##class(%SQL.Statement).%New()
	set status = statement.%PrepareClassQuery("Security.Users", "Detail")
	if $$$ISERR(status) {
		write "%Prepare failed:" do $SYSTEM.Status.DisplayError(status)
		return status
	}

	set rset = statement.%Execute()
	if (rset.%SQLCODE '= 0) {
		write "%Execute failed:", !, "SQLCODE ", rset.%SQLCODE, ": ", rset.%Message 
		return $$$ERROR($$$GeneralError, "%Execute failed, SQLCODE " _ rset.%SQLCODE)
	}

  while rset.%Next()
  {
    set nm = rset.%Get("Name") 
    set fNm = rset.%Get("FullName") 
    set roles = rset.%Get("Roles")
    if ( (nm [ "System") ||( nm [ "Service") || (nm [ "Test") || (nm [ "Admin") || (nm [ "admin") ||
    (fNm [ "System") || (fNm [ "Service") || (fNm [ "Test") || (fNm [ "Admin")
    || (nm [ "IAM") || (nm [ "Unknown") || (nm [ "Ensemble") || (nm [ "PUBLIC") )
    {
	    Write !, "SKIP: " _ nm
    }
    else
    {	
	    SET $NAMESPACE = "EDIPAYER"
	    &SQL(INSERT INTO IHC_ITF_ITFCOMMON_X12.IrisUsers
	    (UserName, FullName, GrantedRoles)
	    values
	    (:nm, :fNm, :roles)) 
	    IF ( (SQLCODE = 0) || (SQLCODE = -119 ))
	    {
	    	WRITE !, "Duplicate or OK"
    	}
    	else
    	{
	    	return $$$ERROR($$$GeneralError, " Insert Error: " _ nm _ ": " _ SQLCODE)
    	}
    	SET $NAMESPACE = "%SYS"

  	}
  	if (rset.%SQLCODE < 0) {
    	return $$$ERROR($$$GeneralError, "%Next failed, SQLCODE: " _ rset.%SQLCODE)
  	}

}
return $$$OK
